<script setup lang="ts">
import {onMounted,watch} from 'vue';
import type {ApiClient} from '@kuaixie/sdk';
import {t,formatDate,formatAmount} from '@kuaixie/i18n';
import {useTradeCases,caseTypes,caseResolutions,caseOutcomes,caseTypeKey,caseOutcomeKey,caseStageKey,caseEventKey,caseRoleKey,caseRefundKey} from './useTradeCases';
const props=defineProps<{client:ApiClient;admin?:boolean;orderId?:string;caseId?:string}>();
const p=useTradeCases(props.client,async(title,body)=>window.confirm(title+'\n'+body),!!props.admin);
watch(()=>props.orderId,value=>{if(value)p.draft.orderId=value},{immediate:true});
watch(()=>props.caseId,value=>{if(value)void p.loadDetail(value)},{immediate:true});
onMounted(()=>{void p.loadList();void p.loadOrders()});
</script>
<template><section class="cases business-card"><h2>{{t('case.title')}}</h2><p>{{t('case.financialNotice')}}</p><p role="alert" v-if="p.error.value">{{p.error.value}}</p><p v-if="p.loading.value">{{t('account.loading')}}</p>
<button :disabled="p.loading.value||!!p.pending.value" @click="p.loadList()">{{t('case.refresh')}}</button>
<div v-for="row in p.rows.value" :key="row.id"><button :disabled="!!p.pending.value" @click="p.loadDetail(row.id)">{{row.order_no||row.order_id}} · {{t(caseStageKey(row.stage))}}</button></div><p v-if="!p.rows.value.length&&!p.loading.value">{{t('case.noCases')}}</p><button v-if="p.more.value" @click="p.loadList(true)">{{t('case.more')}}</button>
<fieldset v-if="!admin" :disabled="p.busy.value||!!p.pending.value"><legend>{{t('v15.disputeCreate')}}</legend><label>{{t('case.selectOrder')}}<select v-model="p.draft.orderId"><option value="">—</option><option v-for="o in p.orders.value" :key="o.id" :value="o.id">{{o.order_no||o.id}} · {{o.item_name}}</option></select></label><button v-if="p.moreOrders.value" @click="p.loadOrders(true)">{{t('case.more')}}</button><label>{{t('v15.disputeType')}}<select v-model="p.draft.type"><option v-for="kind in caseTypes" :key="kind" :value="kind">{{t(caseTypeKey(kind))}}</option></select></label><label>{{t('v15.disputeCreate')}}<textarea v-model="p.draft.description" maxlength="4000"/></label><select v-model="p.draft.expectResolution"><option v-for="v in caseResolutions" :key="v" :value="v">{{t(caseOutcomeKey(v))}}</option></select><input v-if="['refund_part','compensate'].includes(p.draft.expectResolution)" v-model="p.draft.amount" inputmode="decimal" :placeholder="t('v15.refundAmount')"/><label>{{t('case.evidence')}}<textarea v-model="p.draft.evidence"/></label><p>{{t('case.evidenceHint')}}</p><button @click="p.create()">{{t('v15.disputeCreate')}}</button></fieldset>
<article v-if="p.entry.value"><button :disabled="p.loading.value||!!p.pending.value" @click="p.loadDetail(p.entry.value.id)">{{t('v15.refresh')}}</button><h3>{{p.entry.value.order_no||p.entry.value.order_id}} · {{t(caseStageKey(p.entry.value.stage))}}</h3><p>{{t(caseRoleKey(p.entry.value.myRole))}} · {{t('case.round')}} {{p.entry.value.round}}</p><p>{{p.entry.value.description}}</p><p v-if="p.entry.value.negotiation_deadline">{{t('case.deadline')}}: {{formatDate(p.entry.value.negotiation_deadline)}}</p><p v-if="p.entry.value.respondent_note">{{p.entry.value.respondent_note}}</p><p v-if="p.entry.value.refund_amount!=null">{{t('v15.refundAmount')}}: {{formatAmount(p.entry.value.refund_amount,'CNY')}}</p><p v-if="p.entry.value.verdict">{{t(caseOutcomeKey(p.entry.value.verdict))}} · {{p.entry.value.verdict_reason}}</p><p v-if="p.entry.value.refund_status">{{t(caseRefundKey(p.entry.value.refund_status))}}</p><p v-if="p.entry.value.resolved_at">{{formatDate(p.entry.value.resolved_at)}}</p><div v-for="url in [...p.entry.value.evidence_urls,...p.entry.value.respondent_evidence_urls]" :key="url"><a v-if="/^https:\/\/[^\s]+$/i.test(url)" :href="url" target="_blank" rel="noopener noreferrer">{{url}}</a><span v-else>{{url}}</span></div><fieldset :disabled="p.busy.value||!!p.pending.value"><label>{{t('case.note')}}<textarea v-model="p.note.value" maxlength="1000"/></label><label v-if="!admin">{{t('case.evidence')}}<textarea v-model="p.evidence.value"/></label>
<template v-if="admin&&['platform_review','appeal'].includes(p.entry.value.stage)"><select v-model="p.outcome.value"><option v-for="v in caseOutcomes" :key="v" :value="v">{{t(caseOutcomeKey(v))}}</option></select><input v-if="['refund_part','compensate'].includes(p.outcome.value)" v-model="p.amount.value" inputmode="decimal" :placeholder="t('v15.refundAmount')"/><label>{{t('case.deposit')}}<select v-model="p.depositOwner.value"><option value="return_original">{{t('case.returnOriginal')}}</option><option value="buyer">{{t('case.buyer')}}</option><option value="vendor">{{t('case.vendor')}}</option><option value="none">{{t('case.none')}}</option></select></label><button @click="p.act('decide')">{{t('case.decided')}}</button></template>
<template v-if="!admin"><button v-if="['negotiating','platform_review','appeal','awaiting_refund','awaiting_fulfilment'].includes(p.entry.value.stage)" @click="p.act('respond')">{{t('case.responded')}}</button><button v-if="p.entry.value.stage==='negotiating'" @click="p.act('escalate')">{{t('case.escalated')}}</button><button v-if="!p.entry.value.reopened_used&&['resolved','awaiting_refund','awaiting_fulfilment'].includes(p.entry.value.stage)" @click="p.act('appeal')">{{t('case.appealed')}}</button><button v-if="p.entry.value.myRole==='buyer'&&p.entry.value.stage==='awaiting_fulfilment'" @click="p.act('finish')">{{t('case.fulfilled')}}</button></template></fieldset>
<h3>{{t('case.history')}}</h3><div v-for="event in p.entry.value.events" :key="event.id"><strong>{{t(caseEventKey(event.action))}} · {{t(caseRoleKey(event.actor_role))}}</strong><p>{{formatDate(event.created_at)}} · {{event.payload.input.note||event.payload.input.reason||event.payload.input.description}}</p><a v-for="url in (event.payload.input.evidenceUrls||[]).filter(url=>/^https:\/\/[^\s]+$/i.test(url))" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{url}}</a></div><button v-if="p.moreEvents.value" @click="p.history()">{{t('case.more')}}</button></article><button v-if="p.pending.value" :disabled="p.busy.value" @click="p.retry()">{{t('case.retryPending')}}</button></section></template>
<style scoped>.cases{display:grid;gap:12px}.cases fieldset{display:grid;gap:10px;margin-top:16px}.cases label{display:grid;gap:5px}.cases textarea{min-height:80px}.cases input,.cases select,.cases textarea{max-width:100%;padding:9px}.cases button{padding:9px;cursor:pointer}.cases a{display:block;overflow-wrap:anywhere}.cases [role=alert]{color:#b42318}</style>
